effect.shader:
//////////////////////////

vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
#define fragCoord gl_FragCoord.xy

    float min_dist(vec2 v, vec2 w, vec2 p)
    {
        float t = ((p.x - v.x) * (w.x - v.x) + (p.y - v.y) * (w.y - v.y)) /
                        ((w.x - v.x) * (w.x - v.x) + (w.y - v.y) * (w.y - v.y));
        if (t < 0.0)
            return distance(p, v);
        else if (t > 1.0)
            return distance(p, w);
        vec2 op = v + t * (w - v);
        return distance(p, op);
    }

    float rand(float _seed)
    {
        return fract(sin(_seed+137.0) * 43758.5453);
    }

    float ll3(vec2 p1, vec2 p2, vec2 uv)
    {
    	vec2 plast;

    	float mind = 1000000.0;

    	plast = p1;

    	float seed = rand(floor(acTime*40.0));

    	for (int i=0; i < 2; i++)
    	{
    		float tt = float(i+1) / 3.0;

    		vec2 pt = p1 + ((p2 - p1) * tt);
    		float a = rand(seed) * 3.141592 * 2.0;
    		vec2 pn = pt + vec2(cos(a), sin(a)) * rand(seed) / ((abs(tt-0.5)+1.0)*90.0);

    		float d = min_dist(plast, pn, uv);
    		if (d < mind)
    			mind = d;

    		plast = pn;
    		seed = rand(seed);
    	}

    	float d = min_dist(plast, p2, uv);
    	if (d < mind)
    		return d * 3.0;
    	else
    		return mind * 5.0;
    }


    float ll2(vec2 p1, vec2 p2, vec2 uv)
    {
    	vec2 plast;

    	float mind = 1000000.0;

    	plast = p1;

    	float seed = rand(floor(EVO2*15.0));

    	for (int i=0; i < int(SPREAD); i++)
    	{
    		float tt = float(i+1) / 4.0;

    		vec2 pt = p1 + ((p2 - p1) * tt);
    		float a = rand(seed) * 3.141592 * 2.0;
    		vec2 pn = pt + vec2(cos(a), sin(a)) * rand(seed) / ((abs(tt-0.5)+1.0)*30.0);

    		float d = min_dist(plast, pn, uv);
    		if (d < mind)
    			mind = d;

    		vec2 pn2 = pn + vec2(cos(a), sin(a)) * rand(seed) / ((abs(tt-0.5)+1.0)*rand(seed)*30.0);
    		d = ll3(pn, pn2, uv);
    		if (d < mind)
    			mind = d;

    		plast = pn;
    		seed = rand(seed);
    	}

    	float d = min_dist(plast, p2, uv);
    	if (d < mind)
    		return d * 3.0;
    	else
    		return mind * 3.0;
    }
//////////////////////////
    void main() {
    if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
    vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

    vec2 image_size = getTexSize(inputImg.size);
    vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
    vec2 iMouse = vec2(0.5, 0.5);
    float iTime = acTime;

    vec2 umefx;
    umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
    umefx.y*=acLayerSize.y/acLayerSize.x;
    umefx /= scale;
    umefx *= rot2m((0.0+angle)*0.0174533);
    umefx += vec2((-250.0+position.x), (140.0-position.y))*vec2(-1.,1.)/500.;
    vec2 scaleVec;
    scaleVec = vec2(scale*stretch.x,scale*stretch.y);
    umefx /= scaleVec;

    /////////////////////////

	vec4 fragColor;

    	vec2 uv = umefx;
    	vec2 p1 = vec2(0.1, 0.3),
    		 plast,
    		 p2 = vec2(0.9, 0.3);

    	float mind = 1000000.0;

    	plast = p1;

    	float seed = rand(floor(EVO*10.0));

    	for (int i=0; i < int(AMOUNT); i++)
    	{
    		float tt = float(i+1) / 15.0;

    		vec2 pt = p1 + ((p2 - p1) * tt);
    		float a = rand(seed) * 3.141592 * 2.0;
    		vec2 pn = pt + vec2(cos(a), sin(a)) * rand(seed) / ((abs(tt-0.5)+1.0)*9.0);

    		float d = min_dist(plast, pn, uv);
    		if (d < mind)
    			mind = d;

    		vec2 pn2 = pn + vec2(cos(a), sin(a)) * rand(seed) / ((abs(tt-0.5)+1.0)*rand(seed)*6.0);
    		d = ll2(pn, pn2, uv);
    		if (d < mind)
    			mind = d;

    		plast = pn;
    		seed = rand(seed);
    	}

    	float d = min_dist(plast, p2, uv);
    	if (d < mind)
    		mind = d;

    	mind *= 10.0;
    	mind += 1.0;
    	mind = 1.0 / (mind*mind*mind*mind);

    	fragColor = vec4(1.0, 1.0, 1.0, 1.0) * mind;
    	fragColor.r *= mind;
    	fragColor.g *= mind;

	// vec4 factor = mix(texColorX,fragColor,1.0);

	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
        vec4 gradmap;
        float luminance = dot(fragColor.rgb, luminanceWeighting);
        gradmap = mix(color1,color2,luminance)*fragColor.a;
	    vec4 factor = mix(texColorX,gradmap,1.0);

    vec4 resultfinal;
      if( blendMode==0 ) {
        resultfinal = (factor * hardness) * texColor.a; }
        // resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }
      else if( blendMode==1 ) { factor *= hardness;
        vec4 c = factor + vec4(1.)*(1.-factor.a);
        resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
        // resultfinal = min(factor, texColor) * texColor.a; }
      else if( blendMode==2 ) { factor *= hardness; 
        resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
      else if( blendMode==3 ) { factor *= hardness; 
        resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }
          // resultfinal = max(factor, texColor) * texColor.a; }

	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
      }
    }
